import de.mrjulsen.crn.client.gui.widgets.TrainStatsViewer;
import de.mrjulsen.crn.client.gui.widgets.create.CreateButton;
import de.mrjulsen.crn.client.gui.windows.AbstractNavigatorScreen;
import de.mrjulsen.mcdragonlib.client.gui.events.DLGuiStandardEvents;
import de.mrjulsen.mcdragonlib.client.gui.widgets.base.DLGuiComponent;
import de.mrjulsen.mcdragonlib.client.gui.widgets.base.DLWindowManager;
import de.mrjulsen.mcdragonlib.util.TextUtils;
import net.createmod.catnip.gui.element.ScreenElement;
import net.minecraft.network.chat.Component;

public class TrainStatsWindow
extends AbstractNavigatorScreen {
    public TrainStatsWindow(DLWindowManager manager) {
        super(manager, (Component)TextUtils.text((String)"Train Debug Screen"), CreateDynamicWidgets.ContainerColor.PURPLE, CreateDynamicWidgets.BarColor.PURPLE);
        this.pauseGame.set((Object)false);
        manager.setPauseScreen(false);
        int wY = CreateDynamicWidgets.FooterSize.DEFAULT.size() - 1;
        int wH = 247 - wY - CreateDynamicWidgets.FooterSize.SMALL.size();
        TrainStatsViewer viewer = (TrainStatsViewer)this.addComponent(new TrainStatsViewer(3, wY + 2, this.width() - 6, wH - 3));
        viewer.displayTrains();
        CreateButton refreshButton = (CreateButton)this.addComponent((DLGuiComponent)new CreateButton(this.width() - 18 - 8, 223, (ScreenElement)ModGuiIcons.REFRESH.getAsCreateIcon()));
        refreshButton.addEventListener(DLGuiStandardEvents.ClickEvent.class, (s, e) -> {
            viewer.displayTrains();
            return false;
        });
    }
